INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64448449', 64448449, 'analyze_legacy', 'Kab. Bondowoso', 'kabkota', 'Labkesda', 'Belanja Modal Alat Pendingin', 'Barang', 'E-Purchasing', 'Jawa Timur, Bondowoso (Kab.)', 78500000, 'February 2026', 'BLUD', 1, 1, '5', 'AC Standing 5 pk (1 unit) merupakan jenis AC yang unit indoor-nya dirancang untuk berdiri di lantai, bukan dipasang di dinding atau plafon, memiliki kapasitas pendinginan besar, dan cocok untuk ruangan luas seperti hall atau kantor karena pemasangannya fleksibel dan mudah dipindahkan AC 2 pk (1 unit) merupakan Air Conditioner dengan kapasitas pendinginan besar, sekitar 18.000 BTU/h, yang ideal untuk ruangan berukuran 24-41 \\(m^{2}\\) seperti ruang tamu luas, kantor, atau toko. Konsumsi daya listriknya cukup tinggi, sekitar 1.470 hingga 1.920 Watt AC 1 pk (1 unit) merupakan AC dengan kapasitas pendinginan 1 "Paard Kracht" (tenaga kuda), setara sekitar 9.000 BTU/h (British Thermal Unit per jam) atau ~700-1000 Watt, yang cocok untuk mendinginkan ruangan berukuran sekitar 14-18 m² Kulkas 2 pintu (2 unit) merupakan alat elektronik yg memisahkan ruang pendingin (chiller) dan pembeku (freezer) dengan pintu terpisah.', 'AC Standing 5 pk:kapasitas pendinginan sekitar 42.000 - 48.000 Btu/h, daya listrik antara 3700-5000 Watt, seringkali membutuhkan suplai 3 Phase (380-415V), menggunakan freon R410A/R32, dan cocok untuk ruangan 80-120 m² AC 2 pk:kapasitas pendinginan sekitar 18.000 BTU/h, daya listrik antara 1.500-2.000 Watt (bisa lebih rendah untuk inverter), menggunakan refrigeran R32, dan cocok untuk ruangan sekitar 22-42 m² AC 1 pk:kapasitas pendinginan sekitar 9.000 BTU/h (berkisar 8.500-9.500 BTU/h) dan ideal untuk ruangan berukuran 14-17 meter persegi. Konsumsi daya listrik berkisar 600-900 Watt (standard) atau lebih efisien dengan teknologi inverter Kulkas 2 pintu:kapasitas (200-400+ liter), konsumsi daya (sekitar 100-150 Watt), dimensi (lebar 55-70 cm, tinggi 140-180 cm), material rak (sering kali Tempered Glass), fitur hemat energi (Inverter), dan teknologi pendinginan khusus seperti EvenTemp atau 4D Cooling, dengan kompartemen freezer dan pendingin terpisah untuk penyimpanan optimal', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1531923);
