INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62344486', 62344486, 'analyze_legacy', 'Badan Nasional Pencarian dan Pertolongan', 'central', 'Badan Nasional Pencarian dan Pertolongan', 'Manage Service Router Distribution Network (Balai Diklat)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 240024000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Ruang Lingkup pekerjaan Optimalisasi Jaringan Kantor SAR dalam rangka Maintenance IT Support ini mencakup: 1. Menyediakan perangkat nirkabel yang telah memiliki sistem kontrol secara terpusat ( Wireless Controller ), sehingga perubahan topologi jaringan maupun konfigurasi hanya dilakukan pada satu perangkat kontrol. 2. Menyediakan perangkat yang dapat melakukan akses terhadap jaringan infrastruktur IT di Kantor SAR untuk kebutuhan penanggulangan gangguan maupun manajemen melalui jaringan GSM secara aman. 3. Menyediakan perangkat yang dapat melakukan monitoring status dan kondisi perangkat serta ketersediaan layanan IT selama 7x24 jam. 4. Menyediakan perangkat untuk menghubungkan network monitoring penyedia di Kantor SAR ke aplikasi nms.basarnas.go.id dan jaringan LAN kantor pusat. 5. Menyediakan tim NOC yang melakukan kegiatan monitoring selama 7x24 jam dan melakukan penanggulangan gangguan serta pemberitahuan ke Pusdatin melalui aplikasi E-Ticketing. 6. Melakukan kegiatan Preventive Maintenance setiap 2 (dua) kali dalam 1 (satu) tahun. 7. Membuat laporan bulanan yang meliputi laporan kondisi status perangkat, penanggulangan gangguan yang telah dilakukan, memberikan saran dan masukan teknis yang berkaitan dengan layanan Manage Service. 8. Melakukan kegiatan konfigurasi serta perawatan router Mikrotik pada Kantor SAR Badan Nasional Pencarian dan Petolongan. (Kantor SAR Baru) 9. Melakukan kegiatan instalasi dan konfigurasi dari seluruh perangkat Manage Service (WLC, Switch, Access Point, OOB, Stabilizer, Mini PC). (Kantor SAR Baru) 10. Melakukan integrasi koneksi dari perangkat Manage Service ke perangkat eksisting di Kantor SAR. (Kantor SAR Baru) 11. Melakukan implementasi keseragaman SSID Wifi di Kantor SAR menggunakan basarnasservices. (Kantor SAR Baru) 12. Melakukan Relokasi Perangkat Manage Service Kantor SAR Kendari ke ruangan yang baru.', 'Spesifikasi Teknis: Pusat Data dan Informasi Badan Nasional Pencarian dan Pertolongan membutuh Manage Services Jaringan Kantor SAR sebagai berikut: 1. Layanan manage services di UPT 2. Konfigurasi perangkat yang lebih optimal 3. Penerapan keamanan pada perangkat 4. Dukungan pelayanan 24/7 remote atau on-site', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1537070);
