INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64416773', 64416773, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Display Outdoor (DKI JAKARTA)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Sistem', 'Hingga tahun 2024, Badan Meteorologi Klimatologi dan Geofisika (BMKG) memiliki sistem diseminasi informasi MKG dalam bentuk Display Outdoor yang tersebar di 8 (delapan) lokasi, antara lain; 2 site di Jembatan Suramadu (sisi Surabaya dan sisi Madura) yang dibangun tahun 2011, 2 site di Jakarta (Gambir dan Kemenhub) yang dibangun pada tahun 2012, dan masing-masing 1 site di Jayapura, Sorong, Manado, dan Lombok yang dibangun pada tahun 2015. Lingkup kegiatan ini mencakup pemeliharaan Display Outdoor untuk lokasi di DKI Jakarta yaitu lokasi Kemhub dan Gambir, sedangkan untuk lokasi di luar DKI Jakarta telah ditugaskan ke UPT masing - masing lokasi Display. Betapa pentingnya keberadaan display outdoor tersebut sebagai sarana diseminasi informasi MKG untuk kebutuhan masyarakat sekitarnya, maka perlu dilakukan pemeliharaan secara berkala terhadap sistem display tersebut guna menjamin keberlangsungan penyampaian informasi BMKG kemasyarakat.', 'Tujuan dari pelaksanaan kegiatan Pemeliharaan Display outdoor, adalah sebagai berikut : a. Terpeliharanya perangkat Display Outdoor. b. Menjaga kontinyuitas data dan informasi yang diinformasikan ke publik. c. Mempermudah dan mempercepat informasi cuaca untuk masyarakat yang berada di Bandara dan pelabuhan yang hendak bepergian. d. Dapat mensosialisasikan tentang penyebaran produk-produk meteorologi kepada masyarakat, instansi dan pihak yang terkait', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1538161);
